"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["36996"],{10536(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.fora_do_periodo","status":422,"titulo":"A inscri\xe7\xe3o est\xe1 fora do per\xedodo de inscri\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.inscricao.fora_do_periodo","requisitos":["UNI-REQ-0165"],"oQueAconteceu":["A inscri\xe7\xe3o s\xf3 se inicia, se grava, se envia, se corrige, se cancela e se\\ndescarta dentro do per\xedodo de inscri\xe7\xe3o do processo seletivo. O pedido chegou\\nantes do in\xedcio ou depois do fim desse per\xedodo. O per\xedodo \xe9 o do edital\\npublicado, com a prorroga\xe7\xe3o feita por retifica\xe7\xe3o, e o in\xedcio e o fim ainda\\nfazem parte do per\xedodo. A mensagem de detalhe informa, no hor\xe1rio da institui\xe7\xe3o, o in\xedcio e o fim do\\nper\xedodo quando o pedido chegou antes da abertura, e s\xf3 a data de encerramento\\nquando chegou depois.","A consulta da inscri\xe7\xe3o e do comprovante j\xe1 emitido continua dispon\xedvel depois\\ndo encerramento. Iniciar a inscri\xe7\xe3o j\xe1 existente tamb\xe9m s\xf3 a devolve, sem\\ncriar outra."],"comoResolver":["Antes do in\xedcio, volte quando as inscri\xe7\xf5es abrirem. Depois do encerramento,\\nn\xe3o h\xe1 mais como iniciar uma inscri\xe7\xe3o nova, corrigir, cancelar nem descartar; a\\ninscri\xe7\xe3o enviada vale como est\xe1 (UNI-REQ-0165). Se voc\xea acredita que o\\nper\xedodo deveria estar aberto, confira o edital e as retifica\xe7\xf5es, ou fale com\\na unidade respons\xe1vel pelo processo."],"ondeAparece":["In\xedcio da inscri\xe7\xe3o","Grava\xe7\xe3o do rascunho da inscri\xe7\xe3o","Envio da inscri\xe7\xe3o do candidato","Cancelamento da inscri\xe7\xe3o do candidato","Descarte do rascunho da inscri\xe7\xe3o do candidato","Avalia\xe7\xe3o pr\xe9via das respostas da inscri\xe7\xe3o, sem gravar","Envio, confirma\xe7\xe3o e remo\xe7\xe3o de arquivo de documento da inscri\xe7\xe3o"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);